import { ApiError } from '@/lib/http';

export interface ApiErrorCopy {
  message: string;
  traceId?: string;
}

/** mutation 失败的统一文案：优先后端 message，带 traceId 便于排查 */
export function describeApiError(error: unknown, fallback = '操作失败，请稍后重试'): ApiErrorCopy {
  if (error instanceof ApiError) {
    return { message: error.message, traceId: error.traceId };
  }
  if (error instanceof Error && error.message) {
    return { message: error.message };
  }
  return { message: fallback };
}

/** 单句错误文案（不需要 traceId 的提示场景） */
export function describeApiErrorMessage(error: unknown, fallback = '操作失败，请稍后重试'): string {
  return describeApiError(error, fallback).message;
}

/** 乐观锁冲突（HTTP 409）判定：命中时保留表单输入并刷新服务端版本 */
export function isConflictError(error: unknown): boolean {
  return error instanceof ApiError && error.status === 409;
}
